var RESULT_STATUS_RULES = "\u5165\u529B\u306B\u5B9F\u6E2C\u5024\u30FB\u89B3\u6E2C\u7D50\u679C\u3084\u5B9F\u9A13\u5B8C\u4E86\u306E\u8A18\u8FF0\u304C\u3042\u308B\u5834\u5408\u3001\u305D\u306E\u5B9F\u9A13\u306F\u5B8C\u4E86\u6E08\u307F\u3068\u3057\u3066\u4E88\u60F3\uFF0F\u7D50\u679C\u30FB\u8003\u5BDF\u30FB\u7D50\u8AD6\u3092\u66F8\u304F\u3002\u78BA\u8A8D\u6E08\u307F\u306E\u7D50\u679C\u3092\u300C\u898B\u8FBC\u307E\u308C\u308B\u300D\u300C\u4E88\u60F3\u3055\u308C\u308B\u300D\u300C\u671F\u5F85\u3055\u308C\u308B\u300D\u300C\u9054\u6210\u3055\u308C\u308B\u898B\u8FBC\u307F\u300D\u300C\u4ECA\u5F8C\u691C\u8A3C\u3059\u308B\u300D\u306B\u623B\u3059\u3053\u3068\u306F\u7981\u6B62\u3059\u308B\u3002\u7D50\u679C\u306F\u300C\u6B63\u89E3\u7387\u306F92\uFF05\u3067\u3042\u3063\u305F\u300D\u300C\u51E6\u7406\u6642\u9593\u304C20\uFF05\u77ED\u7E2E\u3057\u305F\u300D\u306E\u3088\u3046\u306B\u5F97\u3089\u308C\u305F\u4E8B\u5B9F\u3001\u8003\u5BDF\u306F\u305D\u306E\u7D50\u679C\u306B\u57FA\u3065\u304F\u89E3\u91C8\u3001\u7D50\u8AD6\u306F\u76EE\u7684\u3092\u9054\u6210\u3057\u305F\u7BC4\u56F2\u30FB\u9650\u754C\u3092\u8A00\u3044\u5207\u308B\u3002\u6570\u5024\u30FB\u5358\u4F4D\u30FB\u6BD4\u8F03\u6761\u4EF6\u30FB\u5426\u5B9A\u30FB\u6709\u610F\u5DEE\u306E\u6709\u7121\u3092\u4FDD\u6301\u3057\u3001\u4E0D\u5341\u5206\u306A\u7D50\u679C\u3092\u6210\u529F\u306B\u5909\u3048\u306A\u3044\u3002\u6570\u5024\u304C\u3042\u308B\u3060\u3051\u3067\u5B8C\u4E86\u3068\u306F\u5224\u5B9A\u305B\u305A\u3001\u76EE\u6A19\u5024\u30FB\u4E88\u6E2C\u5024\u30FB\u4F8B\u793A\u30FB\u5F15\u7528\u6587\u732E\u306E\u7D50\u679C\u3092\u5F53\u8A72\u7814\u7A76\u306E\u5B9F\u6E2C\u5024\u306B\u5909\u3048\u306A\u3044\u3002\u672A\u5B9F\u65BD\u306E\u5B9F\u9A13\u3084\u672A\u78BA\u8A8D\u306E\u4E3B\u5F35\u3060\u3051\u306F\u4E88\u60F3\u3068\u3057\u3066\u533A\u5225\u3059\u308B\u3002\u5B9F\u6E2C\u3068\u8A08\u753B\u304C\u6DF7\u5728\u3059\u308B\u5834\u5408\u3082\u78BA\u8A8D\u6E08\u307F\u90E8\u5206\u3092\u672A\u6765\u5F62\u306B\u623B\u3055\u306A\u3044\u3002\u5165\u529B\u306E\u3069\u306E\u9805\u76EE\u306B\u66F8\u304B\u308C\u3066\u3044\u3066\u3082\u5B9F\u6E2C\u7D50\u679C\u3092\u5224\u65AD\u6750\u6599\u3068\u3059\u308B\u3002\u3053\u306E\u6642\u5236\u306E\u533A\u5225\u306F\u539F\u6848\u5206\u89E3\u3001\u9805\u76EE\u63A8\u6572\u3001\u5019\u88DC\u6BD4\u8F03\u30FB\u63A1\u70B9\u3001\u30BF\u30A4\u30C8\u30EB\u30FB\u30A2\u30D6\u30B9\u30C8\u30E9\u30AF\u30C8\u751F\u6210\u306E\u3059\u3079\u3066\u306B\u9069\u7528\u3059\u308B\u3002";
var PROBLEM_CONTENT_RULES = "\u554F\u984C\u306F\u3001\u8AB0\u306B\u30FB\u3069\u306E\u3088\u3046\u306A\u72B6\u6CC1\u3067\u30FB\u3069\u3093\u306A\u5177\u4F53\u7684\u306A\u4E0D\u5229\u76CA\u3084\u652F\u969C\u304C\u751F\u3058\u308B\u304B\u3001\u307E\u305F\u306F\u751F\u3058\u308B\u30EA\u30B9\u30AF\u304C\u3042\u308B\u304B\u3092\u3001\u5C02\u9580\u5916\u306E\u8AAD\u8005\u306B\u3082\u5206\u304B\u308B\u8A00\u8449\u3067\u8FF0\u3079\u308B\u3002\u300C\u5341\u5206\u306B\u89E3\u660E\u3055\u308C\u3066\u3044\u306A\u3044\u300D\u300C\u7814\u7A76\u304C\u306A\u3044\u300D\u300C\u6BD4\u8F03\u3055\u308C\u3066\u3044\u306A\u3044\u300D\u300C\u4E8B\u4F8B\u304C\u306A\u3044\u300D\u306A\u3069\u3001\u77E5\u8B58\u30FB\u7814\u7A76\u30FB\u691C\u8A3C\u306E\u4E0D\u8DB3\u3060\u3051\u3092\u554F\u984C\u3068\u3057\u3066\u4E3B\u5F35\u3059\u308B\u3053\u3068\u306F\u7981\u6B62\u3059\u308B\u3002\u300C\u301C\u3057\u3066\u3044\u306A\u3044\u3068\u3044\u3046\u554F\u984C\u304C\u3042\u308B\u300D\u3068\u8A00\u3044\u63DB\u3048\u3066\u91CD\u5927\u305D\u3046\u306B\u898B\u305B\u306A\u3044\u3002\u7814\u7A76\u4E0A\u306E\u672A\u89E3\u660E\u70B9\u306F\u5FC5\u8981\u306B\u5FDC\u3058\u3066\u76EE\u7684\u3084\u5225\u30D5\u30A3\u30FC\u30EB\u30C9\u306E\u672A\u6C7A\u5B9A\u4E8B\u9805\u306B\u6574\u7406\u3057\u3001\u793E\u4F1A\u30FB\u5B9F\u52D9\u30FB\u5229\u7528\u8005\u306B\u751F\u3058\u308B\u554F\u984C\u3068\u533A\u5225\u3059\u308B\u3002\u300C\u301C\u3068\u3044\u3046\u554F\u984C\u304C\u3042\u308B\u300D\u3068\u3044\u3046\u8A9E\u5C3E\u306F\u5FC5\u9808\u306B\u305B\u305A\u3001\u4E0D\u5229\u76CA\u30FB\u30EA\u30B9\u30AF\u305D\u306E\u3082\u306E\u3092\u5177\u4F53\u7684\u306B\u66F8\u304F\u3002\u5165\u529B\u30FB\u51FA\u5178\u3067\u78BA\u8A8D\u3067\u304D\u308B\u4E8B\u5B9F\u306E\u7BC4\u56F2\u3092\u5B88\u308A\u3001\u95A2\u9023\u304B\u3089\u56E0\u679C\u95A2\u4FC2\u3092\u65AD\u5B9A\u3057\u306A\u3044\u3002SNS\u5229\u7528\u304C\u5B64\u72EC\u611F\u3092\u5F37\u3081\u3001\u5E30\u5C5E\u610F\u8B58\u3092\u4E0B\u3052\u3001\u8106\u5F31\u6027\u3092\u9AD8\u3081\u308B\u3068\u3044\u3063\u305F\u9023\u9396\u3092\u3001\u5165\u529B\u4F8B\u3084\u63A8\u6E2C\u3060\u3051\u3067\u4E8B\u5B9F\u3068\u3057\u3066\u63A1\u7528\u3057\u306A\u3044\u3002\u8AB0\u3082\u304C\u7D0D\u5F97\u3067\u304D\u305D\u3046\u306A\u554F\u984C\u3092\u4F5C\u308B\u305F\u3081\u306B\u3001\u88AB\u5BB3\u30FB\u6DF1\u523B\u3055\u30FB\u666E\u904D\u6027\u3092\u5275\u4F5C\u307E\u305F\u306F\u8A87\u5F35\u3057\u306A\u3044\u3002\u5BFE\u8C61\u3068\u306A\u308B\u4E0D\u5229\u76CA\u3084\u30EA\u30B9\u30AF\u306E\u6839\u62E0\u304C\u8DB3\u308A\u306A\u3051\u308C\u3070\u3001\u5B9F\u5BB3\u3092\u634F\u9020\u3057\u3066\u57CB\u3081\u305A\u3001feedback\u30FBdetails.unresolved\u306A\u3069\u672C\u6587\u3068\u5225\u306E\u6B04\u3067\u3001\u8AB0\u306B\u4F55\u304C\u8D77\u304D\u3066\u56F0\u308B\u306E\u304B\u3068\u5FC5\u8981\u306A\u6839\u62E0\u3092\u5C0B\u306D\u308B\u3002\u539F\u6848\u3092\u5206\u89E3\u3059\u308B\u5834\u5408\u3082\u3001\u672A\u89E3\u660E\u3068\u3044\u3046\u8A18\u8FF0\u304B\u3089\u793E\u4F1A\u7684\u88AB\u5BB3\u3092\u5275\u4F5C\u3057\u306A\u3044\u3002";
var SECTION_ROLES = "\u80CC\u666F\uFF1D\u691C\u8A3C\u3055\u308C\u305F\u4E8B\u5B9F\u306B\u57FA\u3065\u304F\u7814\u7A76\u306E\u524D\u63D0\u3001\u554F\u984C\uFF1D\u5BFE\u8C61\u8005\u3084\u793E\u4F1A\u30FB\u5B9F\u52D9\u306B\u751F\u3058\u308B\u5177\u4F53\u7684\u306A\u4E0D\u5229\u76CA\u30FB\u652F\u969C\u30FB\u30EA\u30B9\u30AF\u3001\u76EE\u7684\uFF1D\u8AD6\u6587\u3067\u793A\u3059\u5177\u4F53\u7684\u5185\u5BB9\u3001\u65B9\u6CD5\uFF1D\u554F\u984C\u89E3\u6C7A\u306E\u305F\u3081\u306E\u8D85\u5177\u4F53\u7684\u3067\u7AEF\u7684\u306A\u624B\u6BB5\u3001\u8AB2\u984C\uFF1D\u305D\u306E\u65B9\u6CD5\u3092\u5B9F\u73FE\u3059\u308B\u4E0A\u3067\u306E\u5177\u4F53\u7684\u3067\u7AEF\u7684\u306A\u969C\u58C1\u3001experiment\uFF08\u8A55\u4FA1\u30FB\u691C\u8A3C\uFF09\uFF1D\u6BD4\u8F03\u5BFE\u8C61\u30FB\u8A55\u4FA1\u6307\u6A19\u30FB\u5B9F\u9A13\u6761\u4EF6\u3001expected_results\uFF08\u4E88\u60F3\uFF0F\u7D50\u679C\uFF09\uFF1D\u4E88\u60F3\u307E\u305F\u306F\u89B3\u6E2C\u7D50\u679C\u3001\u8003\u5BDF\uFF1D\u8AB2\u984C\u304C\u89E3\u6C7A\u3067\u304D\u305F\u304B\u3092\u7D50\u679C\u304B\u3089\u691C\u8A0E\u3059\u308B\u3053\u3068\u3001\u7D50\u8AD6\uFF1D\u5B9F\u6E2C\u7D50\u679C\u304C\u3042\u308B\u5834\u5408\u306F\u76EE\u7684\u306E\u9054\u6210\u5EA6\u3001\u672A\u5B9F\u65BD\u306E\u5834\u5408\u306F\u9054\u6210\u306E\u898B\u8FBC\u307F\u3001\u8CA2\u732E\uFF1D\u554F\u984C\u306E\u89E3\u6C7A\u306E\u3069\u306E\u90E8\u5206\u306B\u3069\u306E\u7A0B\u5EA6\u8CA2\u732E\u3057\u3046\u308B\u304B\u3002";
